'use client';

import { useState } from 'react';

/**
 * Step 8 — the permanent address.
 *
 * The QR is generated by the existing QR service and the destination is the
 * permanent `/m/{publicId}` path. Nothing on this screen can change it, which
 * is the point: prices, photographs, style, brand and offers all change freely
 * behind an address that never moves.
 */
export function QrStep({
  publicUrl,
  publicPath,
  qrSvg,
  downloadBase,
  published,
}: {
  publicUrl: string;
  publicPath: string;
  /** Inline SVG from the QR service — the same artwork the download produces. */
  qrSvg: string;
  downloadBase: string;
  published: boolean;
}) {
  const [copied, setCopied] = useState(false);

  return (
    <div className="build__card">
      <h2 className="build__step-title">Your menu’s permanent address</h2>
      <p className="build__lede">
        Print this code once. Changing your prices, photos, style or brand never changes where it
        points.
      </p>

      <div className="build__qr">
        <div className="build__qr-art" dangerouslySetInnerHTML={{ __html: qrSvg }} />

        <div className="build__qr-details">
          <p className="admin__label">Public link</p>
          <p className="build__url">
            <code>{publicUrl}</code>
          </p>

          <div className="build__actions">
            <button
              type="button"
              className="admin__button admin__button--secondary"
              onClick={async () => {
                try {
                  await navigator.clipboard.writeText(publicUrl);
                  setCopied(true);
                } catch {
                  // Clipboard access can be refused; the link is on screen to
                  // copy by hand, so this is not worth an error dialog.
                  setCopied(false);
                }
              }}
            >
              {copied ? 'Copied' : 'Copy link'}
            </button>

            <a className="admin__button admin__button--secondary" href={`${downloadBase}?artwork=plain&format=svg`}>
              Download QR (SVG)
            </a>
            <a className="admin__button admin__button--secondary" href={`${downloadBase}?artwork=plain&format=png`}>
              Download QR (PNG)
            </a>
          </div>

          {published ? (
            <p className="admin__message admin__message--ok" role="status">
              This link is live. <a href={publicPath} target="_blank" rel="noreferrer">Open it</a>.
            </p>
          ) : (
            <p className="admin__hint">
              The address is reserved and will not change. It starts answering when you publish.
            </p>
          )}
        </div>
      </div>
    </div>
  );
}
